<section class="card"><div class="section-heading"><div><h2><?= e(t('LifeOS assistant')) ?></h2><p class="muted"><?= e(t('Ask a question using a currently available free online model. No local model download is required.')) ?></p></div><form method="post" action="/intelligence/models"><?= csrf_field() ?><button class="secondary"><?= e(t('Refresh free models')) ?></button></form></div>
<p class="footnote"><?= e(t('Only your typed question is sent by default. Free model providers may retain prompts or use them for improvement. Do not include confidential information.')) ?></p>
<p class="notice" data-ai-desktop-missing hidden><?= e(t('Open the LifeOS Windows app to run the AI assistant.')) ?></p>
<?php if($aiModels): ?><form method="post" action="/intelligence/chat" class="stack"><?= csrf_field() ?><label><?= e(t('Free model')) ?><select name="model"><?php foreach($aiModels as $model): ?><option value="<?= e($model['id']) ?>"><?= e($model['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Question')) ?><textarea name="question" rows="4" maxlength="2000" required></textarea></label><label class="checkbox-label"><input name="send_external" type="checkbox" required><?= e(t('Send my typed question to the online AI service.')) ?></label><label class="checkbox-label"><input name="include_totals" type="checkbox"><?= e(t('Also include anonymized work totals, open-task count and this month’s recorded spending.')) ?></label><button><?= e(t('Ask LifeOS')) ?></button></form><?php else: ?><p><?= e(t('Refresh the model list to find currently available zero-cost models.')) ?></p><?php endif; ?>
<?php if($aiJob): ?>
<?php if(in_array($aiJob['status'],['queued','running'],true)): ?><p role="status" data-ai-job-id="<?= e($aiJob['id']) ?>" data-ai-status="<?= e($aiJob['status']) ?>"><?= e(t('The assistant is working in the background. You can keep using LifeOS.')) ?></p>
<?php elseif($aiJob['status']==='failed'): ?><p class="notice warning" role="status"><?= e(t($aiJob['error']??t('The AI service is unavailable. Try again later.'))) ?></p>
<?php elseif($aiJob['kind']==='models'): ?><p role="status"><?= e(t('Free model list refreshed.')) ?></p>
<?php else:$structured=json_decode(trim(preg_replace('/^```(?:json)?\s*|\s*```$/','',$aiJob['answer'])),true);$body=is_array($structured)&&is_string($structured['answer']??null)?$structured['answer']:$aiJob['answer']; ?>
<article class="lesson-entry"><h3><?= e(t('Assistant response')) ?></h3><p><?= nl2br(e($body)) ?></p><p class="footnote"><?= e(t('AI answers may be mistaken. No proposed action runs until you review and confirm it below.')) ?></p></article>
<?php foreach(OpenCodeCliProvider::proposals($aiJob)as $index=>$proposal): ?>
<?php if($proposal['action']==='summarize_week'): ?><a class="btn secondary" href="/roles?view=week"><?= e(t('View recorded weekly totals')) ?></a>
<?php elseif(Db::one('SELECT job_id FROM ai_applied_actions WHERE job_id=? AND action_index=?',[$aiJob['id'],$index])): ?><p><?= e(t('This action was already applied.')) ?></p>
<?php else: ?><form class="form-grid" method="post" action="/intelligence/chat/<?= e($aiJob['id']) ?>/apply"><?= csrf_field() ?><input name="index" type="hidden" value="<?= e($index) ?>">
<?php if($proposal['action']==='add_task'): ?><h3 class="full"><?= e(t('Review proposed task')) ?></h3><label><?= e(t('Title')) ?><input name="title" value="<?= e($proposal['title']) ?>" maxlength="200" required></label><label><?= e(t('Due date (optional)')) ?><input name="due" type="date" value="<?= e($proposal['due']??'') ?>"></label>
<?php else: ?><h3 class="full"><?= e(t('Review proposed expense')) ?></h3><label><?= e(t('Amount in LKR')) ?><input name="amount" type="number" min="0.01" step="0.01" value="<?= e($proposal['amount']) ?>" required></label><label><?= e(t('Date')) ?><input name="date" type="date" value="<?= e($proposal['date']) ?>" required></label><label><?= e(t('Note')) ?><input name="note" value="<?= e($proposal['note']) ?>" maxlength="300" required></label><label><?= e(t('Account')) ?><select name="account_id" required><option value=""><?= e(t('Choose…')) ?></option><?php foreach(Db::all('SELECT id,name FROM accounts ORDER BY name')as $account): ?><option value="<?= e($account['id']) ?>"><?= e($account['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Category')) ?><select name="category_id" required><option value=""><?= e(t('Choose…')) ?></option><?php foreach(Db::all('SELECT id,name FROM expense_categories ORDER BY name')as $category): ?><option value="<?= e($category['id']) ?>"><?= e($category['name']) ?></option><?php endforeach; ?></select></label><?php endif; ?>
<button><?= e(t('Confirm and apply')) ?></button></form><?php endif; ?><?php endforeach; ?>
<?php endif; ?><?php endif; ?></section>
